            'text'::chunks_content_type_enum,
            NULL,
            454,
            86,
            '{"parser": "legacy-migration", "file_name": "סיכום למבחן אחזור מידע (1).pdf", "file_type": "pdf", "legacyData": {"legacy_id": "15777139-1e70-4f84-8fa7-a228c6bcc047", "external_id": null, "collection": "collection", "type": "chunk-data", "tags": "", "user_id": "de0ff05457533c93fdf3e0d1cdd0f808", "create_date": "2025-08-26T11:29:00.383Z", "link_to_file": "https://jeenfilesdevweu.blob.core.windows.net/jeendocs/de0ff05457533c93fdf3e0d1cdd0f808/data/1756207659351-0c8cd1917d00e951630029e4978e9147.pdf", "excerptKeywords": "KEYWORDS: Shingling, k תווים רציפים, מסמכים, קבוצה, אלמנטים"}}'::jsonb,
