            69,
            '{"parser": "legacy-migration", "file_name": "סיכום למבחן אחזור מידע (1).pdf", "file_type": "pdf", "legacyData": {"legacy_id": "25a7c33f-4d8d-4ef1-9eb1-7d1bf6d74f51", "external_id": null, "collection": "collection", "type": "chunk-data", "tags": "", "user_id": "de0ff05457533c93fdf3e0d1cdd0f808", "create_date": "2025-08-26T11:29:00.247Z", "link_to_file": "https://jeenfilesdevweu.blob.core.windows.net/jeendocs/de0ff05457533c93fdf3e0d1cdd0f808/data/1756207659351-0c8cd1917d00e951630029e4978e9147.pdf", "excerptKeywords": "KEYWORDS: זיכרון, מסמך, בלוק, מיון, מיזוג"}}'::jsonb,
